// Lista de id_eap levantada por SQL direto no Supabase (2026-09-18):
//   SELECT id_eap, id_obra, count(*) FROM "EAP" WHERE id_eap IS NOT NULL
//   GROUP BY id_eap, id_obra;
// NÃO é 1 por obra: a obra 107 (NN-AP) tem 6 grupos e a 94 (Porto Itapoá)
// tem 2. Reconsultar se aparecer um grupo novo que não está aqui.
//
// id_eap=66 é da obra 103 (CNPEM - Auditório), que não aparece no painel
// (não está no array OBRAS nem na tabela `obras` do MySQL). Fica incluído
// de propósito: a tabela `EAP` do Supabase JÁ tem as 641 tarefas dela, e
// deixar de fora só criaria um pedaço permanentemente desatualizado da
// mesma tabela. Pra excluir, basta comentar a linha.
const ID_EAP = [
  { id_eap: 51,  id_obra: 91,  nome_obra: 'Novo Nordisk - UB/SP' },
  { id_eap: 32,  id_obra: 94,  nome_obra: 'Porto Itapoá' },
  { id_eap: 121, id_obra: 94,  nome_obra: 'Porto Itapoá' },
  { id_eap: 66,  id_obra: 103, nome_obra: 'CNPEM - Auditório' },
  { id_eap: 73,  id_obra: 106, nome_obra: 'CNPEM - Faseado' },
  { id_eap: 86,  id_obra: 107, nome_obra: 'Novo Nordisk - AP' },
  { id_eap: 87,  id_obra: 107, nome_obra: 'Novo Nordisk - AP' },
  { id_eap: 88,  id_obra: 107, nome_obra: 'Novo Nordisk - AP' },
  { id_eap: 89,  id_obra: 107, nome_obra: 'Novo Nordisk - AP' },
  { id_eap: 90,  id_obra: 107, nome_obra: 'Novo Nordisk - AP' },
  { id_eap: 94,  id_obra: 107, nome_obra: 'Novo Nordisk - AP' },
  { id_eap: 110, id_obra: 108, nome_obra: 'Novo Nordisk - AP - Reforço' },
  { id_eap: 114, id_obra: 110, nome_obra: 'Hitachi' },
  { id_eap: 115, id_obra: 110, nome_obra: 'Hitachi' },
  { id_eap: 127, id_obra: 114, nome_obra: 'IPEN' },
];

return ID_EAP.map(o => ({ json: o }));

// Envelope confirmado contra resposta real (2026-09-18, id_eap=32):
//   {data: {id_eap, nome_eap, id_obra, nome_obra, tarefas: [...]}}
// 'data' é OBJETO (não array) e os campos de cada tarefa já batem 1:1 com
// as colunas da tabela `EAP` do Supabase — nenhuma tradução de nome é
// necessária, só de TIPO (ver `num` abaixo).

const ctx = $('Loop id_eap (1 por vez)').first().json;
const entrada = $input.first().json;

const bruto = typeof entrada === 'string' ? entrada
            : (typeof entrada.data === 'string' ? entrada.data
            : (typeof entrada.body === 'string' ? entrada.body : entrada));
let corpo;
try {
  corpo = typeof bruto === 'string' ? JSON.parse(bruto) : bruto;
} catch (e) {
  throw new Error(`id_eap ${ctx.id_eap}: resposta nao e JSON. Corpo cru (1000 chars): ` + String(bruto).slice(0, 1000));
}

const grupo = corpo && corpo.data ? corpo.data : corpo;
if (!grupo || !Array.isArray(grupo.tarefas)) {
  throw new Error(`id_eap ${ctx.id_eap}: envelope inesperado (esperava data.tarefas[]). Recebido: ` + JSON.stringify(corpo).slice(0, 600));
}

// A origem manda número como string ("254616112.00") e "vazio" como "" —
// string vazia quebra tanto coluna `double precision` no Postgres quanto
// `DOUBLE` no MySQL, então vira null. Datas ficam como STRING de
// propósito (são TEXT/VARCHAR nos dois bancos; a origem manda
// "0000-00-00" e o painel já sabe tratar isso).
const num = (v) => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(String(v).replace(',', '.'));
  return Number.isFinite(n) ? n : null;
};
const txt = (v) => (v === null || v === undefined || v === '' ? null : String(v));

const idObra = num(grupo.id_obra) ?? ctx.id_obra;
const nomeObra = txt(grupo.nome_obra) ?? ctx.nome_obra;
const idEap = num(grupo.id_eap) ?? ctx.id_eap;

const linhas = grupo.tarefas.map(t => ({
  id: num(t.id),
  id_obra: idObra,
  nome_obra: nomeObra,
  id_eap: idEap,
  edt: txt(t.edt),
  tarefa: txt(t.tarefa),
  disciplina: txt(t.disciplina),
  local: txt(t.local),
  unidade: txt(t.unidade),
  qtd: num(t.qtd),
  saldo_qtd: num(t.saldo_qtd),
  efetivo_previsto: txt(t.efetivo_previsto),
  ponderacao_reais: num(t.ponderacao_reais),
  ponderacao_hht: num(t.ponderacao_hht),
  avanco_atual: num(t.avanco_atual),
  desvio: num(t.desvio),
  data_inicio: txt(t.data_inicio),
  data_termino: txt(t.data_termino),
  data_inicio_reprogramado: txt(t.data_inicio_reprogramado),
  data_termino_reprogramado: txt(t.data_termino_reprogramado),
  meta_diaria: num(t.meta_diaria),
  avanco_diario: num(t.avanco_diario),
  encarregado_nome: txt(t.encarregado_nome),
  status_qualidade: txt(t.status_qualidade),
  hht_consumido: num(t.hht_consumido),
}));

const semId = linhas.filter(l => l.id === null).length;
if (semId) throw new Error(`id_eap ${ctx.id_eap}: ${semId} tarefa(s) sem id -- nao da pra fazer upsert sem chave`);

// SQL do MySQL montado aqui como string pronta: o campo "Query
// Parameters" do node MySQL nativo não é confiável entre versões do n8n
// (lição já registrada no snippet de Restrições/OC), então a query inteira
// vai como expressão.
const COLUNAS = Object.keys(linhas[0] || { id: null });
const escapar = (v) => "'" + String(v).replace(/\\/g, '\\\\').replace(/'/g, "\\'") + "'";
const sqlVal = (v) => (v === null || v === undefined) ? 'NULL' : (typeof v === 'number' ? String(v) : escapar(v));
const colsSql = COLUNAS.map(c => '`' + c + '`').join(',');
const tuplas = linhas.map(l => '(' + COLUNAS.map(c => sqlVal(l[c])).join(',') + ')').join(',\n');
const updSql = COLUNAS.filter(c => c !== 'id').map(c => '`' + c + '` = VALUES(`' + c + '`)').join(', ');
const sqlMySql = linhas.length
  ? `INSERT INTO eap_tarefas (${colsSql}) VALUES ${tuplas} ON DUPLICATE KEY UPDATE ${updSql}`
  : 'SELECT 1';

return [{ json: { id_eap: idEap, id_obra: idObra, total: linhas.length, linhas, sqlMySql } }];
